// Domain schema. Auth tables (user, session, project = BetterAuth organization, …) live in auth-schema.ts.
//
// Conventions (ADR 0003, 0012, 0020):
// - every row carries `project_id`; same-project references use composite FKs on (project_id, id)
// - UUIDv7 primary keys generated by the application
// - entity tables have `version` (optimistic concurrency) and `deleted_at` (soft delete)
// - link tables (subjects, participants, edges, attachments) are hard-deleted; the audit log keeps their history
import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  customType,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import { project, user } from "./auth-schema.js";

const tsvector = customType<{ data: string }>({ dataType: () => "tsvector" });

const ts = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

const projectId = () =>
  text("project_id")
    .notNull()
    .references(() => project.id, { onDelete: "cascade" });

const entityColumns = () => ({
  id: uuid("id").primaryKey(),
  projectId: projectId(),
  version: integer("version").notNull().default(1),
  createdAt: ts("created_at").notNull().defaultNow(),
  updatedAt: ts("updated_at").notNull().defaultNow(),
  createdBy: text("created_by").references(() => user.id, { onDelete: "set null" }),
  deletedAt: ts("deleted_at"),
});

// ---------------------------------------------------------------------------
// Lookups seeded per project (ADR 0003)

export const channel = pgTable(
  "channel",
  {
    ...entityColumns(),
    name: text("name").notNull(),
    kind: text("kind").notNull().default("other"), // email | phone | linkedin | job_board | careers_site | messenger | other
    url: text("url"),
  },
  (t) => [unique("channel_project_id_id").on(t.projectId, t.id)],
);

export const positionStage = pgTable(
  "position_stage",
  {
    ...entityColumns(),
    key: text("key").notNull(),
    label: text("label").notNull(),
    order: integer("order").notNull(),
    suggestOnActionTypes: text("suggest_on_action_types").array().notNull().default(sql`'{}'::text[]`),
  },
  (t) => [
    unique("position_stage_project_id_id").on(t.projectId, t.id),
    uniqueIndex("position_stage_key_uq").on(t.projectId, t.key).where(sql`${t.deletedAt} is null`),
  ],
);

// ---------------------------------------------------------------------------
// Organizations, contacts (ADR 0002)

export const organization = pgTable(
  "organization",
  {
    ...entityColumns(),
    kind: text("kind").notNull(), // company | agency
    name: text("name").notNull(),
    website: text("website"),
    notes: text("notes"),
    search: tsvector("search").generatedAlwaysAs(
      sql`to_tsvector('simple', coalesce(name, '') || ' ' || coalesce(website, '') || ' ' || coalesce(notes, ''))`,
    ),
  },
  (t) => [
    unique("organization_project_id_id").on(t.projectId, t.id),
    check("organization_kind_ck", sql`${t.kind} in ('company', 'agency')`),
    index("organization_search_idx").using("gin", t.search),
  ],
);

export const contact = pgTable(
  "contact",
  {
    ...entityColumns(),
    name: text("name").notNull(),
    notes: text("notes"),
    search: tsvector("search").generatedAlwaysAs(
      sql`to_tsvector('simple', coalesce(name, '') || ' ' || coalesce(notes, ''))`,
    ),
  },
  (t) => [unique("contact_project_id_id").on(t.projectId, t.id), index("contact_search_idx").using("gin", t.search)],
);

export const contactAffiliation = pgTable(
  "contact_affiliation",
  {
    ...entityColumns(),
    contactId: uuid("contact_id").notNull(),
    organizationId: uuid("organization_id").notNull(),
    title: text("title"),
    fromDate: date("from_date"),
    toDate: date("to_date"),
  },
  (t) => [
    foreignKey({ columns: [t.projectId, t.contactId], foreignColumns: [contact.projectId, contact.id] }).onDelete(
      "cascade",
    ),
    foreignKey({
      columns: [t.projectId, t.organizationId],
      foreignColumns: [organization.projectId, organization.id],
    }).onDelete("cascade"),
    index("contact_affiliation_contact_idx").on(t.contactId),
    index("contact_affiliation_org_idx").on(t.organizationId),
  ],
);

export const contactHandle = pgTable(
  "contact_handle",
  {
    ...entityColumns(),
    contactId: uuid("contact_id").notNull(),
    channelId: uuid("channel_id").notNull(),
    value: text("value").notNull(),
  },
  (t) => [
    foreignKey({ columns: [t.projectId, t.contactId], foreignColumns: [contact.projectId, contact.id] }).onDelete(
      "cascade",
    ),
    foreignKey({ columns: [t.projectId, t.channelId], foreignColumns: [channel.projectId, channel.id] }),
    index("contact_handle_contact_idx").on(t.contactId),
    index("contact_handle_value_idx").on(t.projectId, t.value),
  ],
);

// ---------------------------------------------------------------------------
// Positions (ADR 0002, 0014, 0026)

export const position = pgTable(
  "position",
  {
    ...entityColumns(),
    title: text("title").notNull(),
    companyId: uuid("company_id"),
    agencyId: uuid("agency_id"),
    url: text("url"),
    descriptionMarkdown: text("description_markdown"),
    salaryMin: numeric("salary_min", { mode: "number" }),
    salaryMax: numeric("salary_max", { mode: "number" }),
    salaryCurrency: text("salary_currency"),
    salaryPeriod: text("salary_period"),
    stageId: uuid("stage_id").notNull(),
    outcome: text("outcome").notNull().default("open"),
    sourceChannelId: uuid("source_channel_id"),
    notes: text("notes"),
    search: tsvector("search").generatedAlwaysAs(
      sql`to_tsvector('simple', coalesce(title, '') || ' ' || coalesce(description_markdown, '') || ' ' || coalesce(notes, ''))`,
    ),
  },
  (t) => [
    unique("position_project_id_id").on(t.projectId, t.id),
    foreignKey({
      name: "position_company_fk",
      columns: [t.projectId, t.companyId],
      foreignColumns: [organization.projectId, organization.id],
    }),
    foreignKey({
      name: "position_agency_fk",
      columns: [t.projectId, t.agencyId],
      foreignColumns: [organization.projectId, organization.id],
    }),
    foreignKey({
      name: "position_stage_fk",
      columns: [t.projectId, t.stageId],
      foreignColumns: [positionStage.projectId, positionStage.id],
    }),
    foreignKey({
      name: "position_source_channel_fk",
      columns: [t.projectId, t.sourceChannelId],
      foreignColumns: [channel.projectId, channel.id],
    }),
    check("position_outcome_ck", sql`${t.outcome} in ('open', 'accepted', 'rejected', 'withdrawn', 'ghosted')`),
    index("position_company_idx").on(t.companyId),
    index("position_agency_idx").on(t.agencyId),
    index("position_stage_idx").on(t.stageId),
    index("position_search_idx").using("gin", t.search),
  ],
);

// ---------------------------------------------------------------------------
// Actions and the action graph (ADR 0004, 0005, 0013, 0029)

export const action = pgTable(
  "action",
  {
    ...entityColumns(),
    type: text("type").notNull(),
    status: text("status").notNull(),
    title: text("title").notNull(),
    notes: text("notes"),
    scheduledAt: ts("scheduled_at"),
    completedAt: ts("completed_at"),
    dueAt: ts("due_at"),
    channelId: uuid("channel_id"),
    assigneeId: text("assignee_id").references(() => user.id, { onDelete: "set null" }),
    payload: jsonb("payload").notNull().default({}),
    search: tsvector("search").generatedAlwaysAs(
      sql`to_tsvector('simple', coalesce(title, '') || ' ' || coalesce(notes, '')) || jsonb_to_tsvector('simple', payload, '["string"]')`,
    ),
  },
  (t) => [
    unique("action_project_id_id").on(t.projectId, t.id),
    foreignKey({
      name: "action_channel_fk",
      columns: [t.projectId, t.channelId],
      foreignColumns: [channel.projectId, channel.id],
    }),
    index("action_project_scheduled_idx").on(t.projectId, t.scheduledAt),
    index("action_project_due_idx").on(t.projectId, t.dueAt),
    index("action_assignee_idx").on(t.assigneeId),
    index("action_search_idx").using("gin", t.search),
  ],
);

export const actionSubject = pgTable(
  "action_subject",
  {
    id: uuid("id").primaryKey(),
    projectId: projectId(),
    actionId: uuid("action_id").notNull(),
    positionId: uuid("position_id"),
    organizationId: uuid("organization_id"),
  },
  (t) => [
    foreignKey({
      name: "action_subject_action_fk",
      columns: [t.projectId, t.actionId],
      foreignColumns: [action.projectId, action.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "action_subject_position_fk",
      columns: [t.projectId, t.positionId],
      foreignColumns: [position.projectId, position.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "action_subject_org_fk",
      columns: [t.projectId, t.organizationId],
      foreignColumns: [organization.projectId, organization.id],
    }).onDelete("cascade"),
    check("action_subject_exactly_one_ck", sql`num_nonnulls(${t.positionId}, ${t.organizationId}) = 1`),
    uniqueIndex("action_subject_position_uq").on(t.actionId, t.positionId).where(sql`${t.positionId} is not null`),
    uniqueIndex("action_subject_org_uq").on(t.actionId, t.organizationId).where(sql`${t.organizationId} is not null`),
    index("action_subject_position_idx").on(t.positionId),
    index("action_subject_org_idx").on(t.organizationId),
  ],
);

export const actionParticipant = pgTable(
  "action_participant",
  {
    projectId: projectId(),
    actionId: uuid("action_id").notNull(),
    contactId: uuid("contact_id").notNull(),
    role: text("role").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.actionId, t.contactId, t.role] }),
    foreignKey({
      name: "action_participant_action_fk",
      columns: [t.projectId, t.actionId],
      foreignColumns: [action.projectId, action.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "action_participant_contact_fk",
      columns: [t.projectId, t.contactId],
      foreignColumns: [contact.projectId, contact.id],
    }).onDelete("cascade"),
    index("action_participant_contact_idx").on(t.contactId),
  ],
);

export const actionEdge = pgTable(
  "action_edge",
  {
    projectId: projectId(),
    parentId: uuid("parent_id").notNull(),
    childId: uuid("child_id").notNull(),
    kind: text("kind").notNull(),
    note: text("note"),
    createdAt: ts("created_at").notNull().defaultNow(),
    createdBy: text("created_by").references(() => user.id, { onDelete: "set null" }),
  },
  (t) => [
    primaryKey({ columns: [t.parentId, t.childId, t.kind] }),
    foreignKey({
      name: "action_edge_parent_fk",
      columns: [t.projectId, t.parentId],
      foreignColumns: [action.projectId, action.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "action_edge_child_fk",
      columns: [t.projectId, t.childId],
      foreignColumns: [action.projectId, action.id],
    }).onDelete("cascade"),
    check("action_edge_no_self_loop_ck", sql`${t.parentId} <> ${t.childId}`),
    index("action_edge_child_idx").on(t.childId),
  ],
);

// ---------------------------------------------------------------------------
// Documents (ADR 0006, 0025)

export const documentTemplate = pgTable(
  "document_template",
  {
    ...entityColumns(),
    name: text("name").notNull(),
    notes: text("notes"),
  },
  (t) => [unique("document_template_project_id_id").on(t.projectId, t.id)],
);

export type TemplateFile = { name: string; blobKey: string; size: number; sha256: string };

export const documentTemplateVersion = pgTable(
  "document_template_version",
  {
    id: uuid("id").primaryKey(),
    projectId: projectId(),
    templateId: uuid("template_id").notNull(),
    versionNo: integer("version_no").notNull(),
    files: jsonb("files").$type<TemplateFile[]>().notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
    createdBy: text("created_by").references(() => user.id, { onDelete: "set null" }),
  },
  (t) => [
    unique("document_template_version_project_id_id").on(t.projectId, t.id),
    unique("document_template_version_no_uq").on(t.templateId, t.versionNo),
    foreignKey({
      name: "document_template_version_template_fk",
      columns: [t.projectId, t.templateId],
      foreignColumns: [documentTemplate.projectId, documentTemplate.id],
    }).onDelete("cascade"),
  ],
);

export const document = pgTable(
  "document",
  {
    ...entityColumns(),
    kind: text("kind").notNull(),
    title: text("title").notNull(),
    positionId: uuid("position_id"),
    derivedFromVersionId: uuid("derived_from_version_id"),
    notes: text("notes"),
  },
  (t) => [
    unique("document_project_id_id").on(t.projectId, t.id),
    foreignKey({
      name: "document_position_fk",
      columns: [t.projectId, t.positionId],
      foreignColumns: [position.projectId, position.id],
    }),
    index("document_position_idx").on(t.positionId),
  ],
);

export const documentVersion = pgTable(
  "document_version",
  {
    id: uuid("id").primaryKey(),
    projectId: projectId(),
    documentId: uuid("document_id").notNull(),
    versionNo: integer("version_no").notNull(),
    // Binary versions: the uploaded file. LaTeX versions: source text plus a pinned template version.
    blobKey: text("blob_key"),
    filename: text("filename").notNull(),
    mime: text("mime").notNull(),
    size: integer("size").notNull(),
    sha256: text("sha256").notNull(),
    source: text("source"),
    templateVersionId: uuid("template_version_id"),
    pdfBlobKey: text("pdf_blob_key"),
    compileStatus: text("compile_status"),
    compileLog: text("compile_log"),
    compiledAt: ts("compiled_at"),
    createdAt: ts("created_at").notNull().defaultNow(),
    createdBy: text("created_by").references(() => user.id, { onDelete: "set null" }),
  },
  (t) => [
    unique("document_version_project_id_id").on(t.projectId, t.id),
    unique("document_version_no_uq").on(t.documentId, t.versionNo),
    foreignKey({
      name: "document_version_document_fk",
      columns: [t.projectId, t.documentId],
      foreignColumns: [document.projectId, document.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "document_version_template_fk",
      columns: [t.projectId, t.templateVersionId],
      foreignColumns: [documentTemplateVersion.projectId, documentTemplateVersion.id],
    }),
    check("document_version_content_ck", sql`num_nonnulls(${t.blobKey}, ${t.source}) = 1`),
  ],
);

export const actionAttachment = pgTable(
  "action_attachment",
  {
    projectId: projectId(),
    actionId: uuid("action_id").notNull(),
    documentVersionId: uuid("document_version_id").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.actionId, t.documentVersionId] }),
    foreignKey({
      name: "action_attachment_action_fk",
      columns: [t.projectId, t.actionId],
      foreignColumns: [action.projectId, action.id],
    }).onDelete("cascade"),
    // No cascade: a version referenced by an action must not disappear (ADR 0006).
    foreignKey({
      name: "action_attachment_version_fk",
      columns: [t.projectId, t.documentVersionId],
      foreignColumns: [documentVersion.projectId, documentVersion.id],
    }),
    index("action_attachment_version_idx").on(t.documentVersionId),
  ],
);

// ---------------------------------------------------------------------------
// Collaboration (ADR 0015, 0016)

export const comment = pgTable(
  "comment",
  {
    id: uuid("id").primaryKey(),
    projectId: projectId(),
    targetType: text("target_type").notNull(),
    targetId: uuid("target_id").notNull(),
    authorId: text("author_id").references(() => user.id, { onDelete: "set null" }),
    body: text("body").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
    editedAt: ts("edited_at"),
    deletedAt: ts("deleted_at"),
  },
  (t) => [index("comment_target_idx").on(t.projectId, t.targetType, t.targetId)],
);

export const notification = pgTable(
  "notification",
  {
    id: uuid("id").primaryKey(),
    projectId: projectId(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(), // assigned | comment
    entityType: text("entity_type").notNull(),
    entityId: uuid("entity_id").notNull(),
    message: text("message").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
    readAt: ts("read_at"),
  },
  (t) => [index("notification_user_idx").on(t.userId, t.readAt)],
);

// ---------------------------------------------------------------------------
// Audit (ADR 0012)

export const auditEvent = pgTable(
  "audit_event",
  {
    id: uuid("id").primaryKey(),
    projectId: projectId(),
    actorUserId: text("actor_user_id").references(() => user.id, { onDelete: "set null" }),
    via: text("via").notNull(),
    entityType: text("entity_type").notNull(),
    entityId: text("entity_id").notNull(),
    op: text("op").notNull(), // create | update | delete | restore | purge | link | unlink
    diff: jsonb("diff"),
    at: ts("at").notNull().defaultNow(),
  },
  (t) => [index("audit_event_entity_idx").on(t.projectId, t.entityType, t.entityId, t.at)],
);

// ---------------------------------------------------------------------------
// Instance-level sign-up invitations (ADR 0021). Project invitations live in BetterAuth's table.

export const instanceInvitation = pgTable("instance_invitation", {
  id: uuid("id").primaryKey(),
  email: text("email").notNull().unique(),
  invitedBy: text("invited_by").references(() => user.id, { onDelete: "set null" }),
  createdAt: ts("created_at").notNull().defaultNow(),
  usedAt: ts("used_at"),
});

// ---------------------------------------------------------------------------
// In-app assistant (ADR 0031). Chats are private to their author and hard-deleted; they are not domain data.

/** A user's API key for one model provider, encrypted with a key derived from BETTER_AUTH_SECRET. */
export const aiCredential = pgTable(
  "ai_credential",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    provider: text("provider").notNull(),
    encryptedKey: text("encrypted_key").notNull(),
    last4: text("last4").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.provider] })],
);

export const chat = pgTable(
  "chat",
  {
    id: uuid("id").primaryKey(),
    projectId: projectId(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    model: text("model").notNull(), // provider:modelId
    approvalMode: text("approval_mode").notNull(),
    webSearch: boolean("web_search").notNull().default(false),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [index("chat_owner_idx").on(t.projectId, t.userId, t.updatedAt)],
);

/** One AI SDK UIMessage; `id` is generated by the client (user messages) or the server (assistant messages). */
export const chatMessage = pgTable(
  "chat_message",
  {
    chatId: uuid("chat_id")
      .notNull()
      .references(() => chat.id, { onDelete: "cascade" }),
    id: text("id").notNull(),
    seq: integer("seq").notNull(),
    role: text("role").notNull(),
    parts: jsonb("parts").notNull(),
    metadata: jsonb("metadata"),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.chatId, t.id] }), index("chat_message_seq_idx").on(t.chatId, t.seq)],
);

export const chatAttachment = pgTable(
  "chat_attachment",
  {
    id: uuid("id").primaryKey(),
    chatId: uuid("chat_id")
      .notNull()
      .references(() => chat.id, { onDelete: "cascade" }),
    blobKey: text("blob_key").notNull(),
    filename: text("filename").notNull(),
    mime: text("mime").notNull(),
    size: integer("size").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [index("chat_attachment_chat_idx").on(t.chatId)],
);

// ---------------------------------------------------------------------------
// Assistant memory (ADR 0032): notes agents reuse across conversations. Project memory is project data shared with
// every member; user memory is private to its user and applies in all of their projects.

export const projectMemory = pgTable(
  "project_memory",
  {
    ...entityColumns(),
    title: text("title").notNull(),
    content: text("content").notNull(),
  },
  (t) => [index("project_memory_project_idx").on(t.projectId)],
);

export const userMemory = pgTable(
  "user_memory",
  {
    id: uuid("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    version: integer("version").notNull().default(1),
    title: text("title").notNull(),
    content: text("content").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [index("user_memory_user_idx").on(t.userId)],
);
